function getFreshdeskAiTranslation(key, lang) {
  if (freshdeskAiTranslations[lang] && freshdeskAiTranslations[lang][key]) {
    return freshdeskAiTranslations[lang][key];
  }
  if (freshdeskAiTranslations.en && freshdeskAiTranslations.en[key]) {
    return freshdeskAiTranslations.en[key];
  }
  return null;
}

function applyFreshdeskAiTranslations(lang) {
  
  let count = 0;
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (key && (key.startsWith('review.freshdesk-ai.') || key.startsWith('review.common.'))) {
      const translation = getFreshdeskAiTranslation(key, lang);
      if (translation) {
        element.textContent = translation;
        count++;
      }
    }
  });
  
}

document.addEventListener('languageChanged', (e) => {
  const lang = e.detail.language;
  setTimeout(() => applyFreshdeskAiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyFreshdeskAiTranslations(currentLang);
  });
} else {
  const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
  applyFreshdeskAiTranslations(currentLang);
}


